import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {createReviewStore,localReviewRequest} from '../tools/sprite-review/store.js';
import {applySelections} from '../tools/sprite-review/apply.js';
const root=await fs.mkdtemp(path.join(os.tmpdir(),'legendgirl-sprite-review-'));
try{
 const data=Buffer.from('imagem de teste'),sha256=crypto.createHash('sha256').update(data).digest('hex');
 await fs.mkdir(path.join(root,'assets'));await fs.writeFile(path.join(root,'assets/sprite.png'),data);await fs.writeFile(path.join(root,'assets/manter.png'),data);
 const catalog={version:'v1',items:[{id:'file',kind:'file',path:'assets/sprite.png',sha256,usage:'nao-localizado',references:[]},{id:'keep',kind:'file',path:'assets/manter.png',sha256,usage:'runtime',references:[]},{id:'crop',kind:'region',path:'assets/sprite.png',parentId:'file',sha256,usage:'runtime',references:[],region:{x:0,y:0,width:1,height:1}},{id:'code',kind:'code',path:'src/renderer.js',sha256:'code',usage:'runtime',references:[],signature:{symbol:'render',variant:'old'}}]};
 const catalogPath=path.join(root,'catalog.json'),selectionPath=path.join(root,'selection.json');await fs.writeFile(catalogPath,JSON.stringify(catalog));
 const store=createReviewStore({catalogPath,selectionPath});assert.equal((await store.read()).revision,0);
 const saved=await store.save({catalogVersion:'v1',revision:0,decisions:{file:'old',keep:'current',crop:'old',code:'old'}});
 assert.deepEqual(saved.selectedForDeletion.map(i=>i.path),['assets/sprite.png']);assert.equal(saved.selectedRegions.length,1);assert.equal(saved.selectedCode.length,1);
 assert.deepEqual(await createReviewStore({catalogPath,selectionPath}).read(),saved,'Escolhas persistem depois de reiniciar a página/servidor.');
 await assert.rejects(store.save({catalogVersion:'v1',revision:0,decisions:{}}),/outra página/);
 await assert.rejects(store.save({catalogVersion:'v1',revision:1,decisions:{'../../escape':'old'}}),/fora do catálogo/);
 await assert.rejects(store.save({catalogVersion:'v1',revision:1,decisions:{file:'delete-all'}}),/inválida/);
 const outcomes=await Promise.allSettled([store.save({catalogVersion:'v1',revision:1,decisions:{file:'old'}}),store.save({catalogVersion:'v1',revision:1,decisions:{keep:'old'}})]);assert.equal(outcomes.filter(r=>r.status==='fulfilled').length,1,'Não perde alterações em duas gravações concorrentes.');
 assert.ok(localReviewRequest({headers:{host:'127.0.0.1:3002',origin:'http://127.0.0.1:3002'},socket:{remoteAddress:'127.0.0.1'}}));
 assert.equal(localReviewRequest({headers:{host:'127.0.0.1:3002',origin:'https://outra-pagina.example'},socket:{remoteAddress:'127.0.0.1'}}),false);
 const dry=await applySelections({root,catalog,selection:saved});assert.equal(dry.applied,false);await fs.access(path.join(root,'assets/sprite.png'));
 const conflicting={...saved,decisions:{...saved.decisions,crop:'current'}};await assert.rejects(applySelections({root,catalog,selection:conflicting,apply:true}),/recorte marcado como atual/);
 const tampered={...saved,selectedForDeletion:[{...saved.selectedForDeletion[0],path:'assets/manter.png'}]};await assert.rejects(applySelections({root,catalog,selection:tampered,apply:true}),/não autorizada/);
 const applied=await applySelections({root,catalog,selection:saved,apply:true});assert.ok(applied.applied);await assert.rejects(fs.access(path.join(root,'assets/sprite.png')));await fs.access(path.join(root,'assets/manter.png'));await fs.access(path.join(root,applied.quarantine,'assets/sprite.png'));
 const referenced={...saved,decisions:{keep:'old'},selectedForDeletion:[{id:'keep',path:'assets/manter.png',sha256}]};await assert.rejects(applySelections({root,catalog,selection:referenced,apply:true}),/referenciados/);
 console.log('APROVADO: JSON persistente, revisão concorrente, alvos exatos, conflito de prancha, simulação, quarentena e proteção de referências.');
}finally{await fs.rm(root,{recursive:true,force:true});}
